        "content": "export interface DiskLook {\n  brightness: number;\n  speed: number;\n  stretch: number;\n  detail: number;\n  turbulence: number;\n  density: number;\n  doppler: number;\n  cloudScale: number;\n  cloudSpeed: number;\n  cloudStrength: number;\n  spare0: number;\n  spare1: number;\n  spare2: number;\n  spare3: number;\n}\n\nexport interface StarLook {\n  brightness: number;\n  density: number;\n  contrast: number;\n  warmth: number;\n  twinkle: number;\n}\n\nexport interface BloomLook {\n  strength: number;\n  threshold: number;\n  knee: number;\n  radius: number;\n}\n\nexport interface HeroSettings {\n  cameraY: number;\n  distance: number;\n  diskRadius: number;\n  fov: number;\n  centerX: number;\n  centerY: number;\n  cameraRoll: number;\n  debugView: number;\n  aa: number;\n  diskLayers: number;\n  mouseYaw: number;\n  sideFade: number;\n  centerFade: number;\n  bloom: BloomLook;\n  disk: DiskLook;\n  stars: StarLook;\n}\n\n/** Shared deterministic production defaults for the browser and headless renderer. */\nexport function defaultHeroSettings(): HeroSettings {\n  return {\n    cameraY: 0.16,\n    distance: 13.5,\n    diskRadius: 9,\n    fov: 3,\n    centerX: 0.8,\n    centerY: 0.3,\n    cameraRoll: -0.27,\n    debugView: 0,\n    diskLayers: 2,\n    aa: 1,\n    mouseYaw: 0.15,\n    sideFade: 1,\n    centerFade: 0,\n    bloom: { strength: 1, threshold: 0, knee: 0.18, radius: 1.5 },\n    disk: {\n      brightness: 0.75,\n      speed: 0.75,\n      stretch: 5.75,\n      detail: 3.44,\n      turbulence: 4.46,\n      density: 1.38,\n      doppler: 1.21,\n      cloudScale: 20,\n      cloudSpeed: 0.3,\n      cloudStrength: 0.2,\n      spare0: 0.43,\n      spare1: -0.25,\n      spare2: -0.67,\n      spare3: 0.69,\n    },\n    stars: { brightness: 1, density: 1, contrast: 13, warmth: 0.5, twinkle: 0 },\n  };\n}\n"
